from pathlib import Path

SIMULATOR = r'''import hashlib
import json
import math

TERMINAL = {
    "DENIED", "TURN_LIMIT", "BUDGET_LIMIT", "COMPLETED",
    "AUTH_CHANGED", "REVALIDATION_FAILED", "STALE_APPROVAL",
    "REPLAY_BLOCKED", "RECONCILIATION_REQUIRED"
}


class BrakeError(Exception):
    pass


def _valid_nonempty_string(value):
    return isinstance(value, str) and bool(value.strip())


def _valid_int(value, minimum=None, maximum=None):
    if not isinstance(value, int) or isinstance(value, bool):
        return False
    if minimum is not None and value < minimum:
        return False
    if maximum is not None and value > maximum:
        return False
    return True


def _validate_json_value(value, active=None):
    if active is None:
        active = set()
    if value is None or isinstance(value, (str, bool)):
        return
    if isinstance(value, int) and not isinstance(value, bool):
        return
    if isinstance(value, float):
        if not math.isfinite(value):
            raise BrakeError("value must be canonical JSON")
        return
    if isinstance(value, (list, dict)):
        marker = id(value)
        if marker in active:
            raise BrakeError("value must be canonical JSON")
        active.add(marker)
        try:
            if isinstance(value, list):
                for item in value:
                    _validate_json_value(item, active)
            else:
                for key, item in value.items():
                    if not isinstance(key, str):
                        raise BrakeError("value must be canonical JSON")
                    _validate_json_value(item, active)
        finally:
            active.remove(marker)
        return
    raise BrakeError("value must be canonical JSON")


def canonical(value):
    try:
        _validate_json_value(value)
        return json.dumps(
            value,
            sort_keys=True,
            separators=(",", ":"),
            allow_nan=False
        )
    except BrakeError:
        raise
    except (TypeError, ValueError, OverflowError, RecursionError) as exc:
        raise BrakeError("value must be canonical JSON") from exc


def digest(value):
    return hashlib.sha256(canonical(value).encode()).hexdigest()


def _valid_digest(value):
    if not isinstance(value, str) or len(value) != 64:
        return False
    return all(character in "0123456789abcdef" for character in value)


def _object_without_duplicates(pairs):
    result = {}
    for key, value in pairs:
        if key in result:
            raise ValueError("duplicate object key")
        result[key] = value
    return result


class Run:
    def __init__(self, run_id, max_turns, budget_units, auth_version="auth-v1", policy_version="policy-v1"):
        if not _valid_nonempty_string(run_id):
            raise BrakeError("run_id must be a nonempty string")
        if not _valid_int(max_turns, minimum=1):
            raise BrakeError("max_turns must be a positive integer")
        if not _valid_int(budget_units, minimum=1):
            raise BrakeError("budget_units must be a positive integer")
        if not _valid_nonempty_string(auth_version):
            raise BrakeError("auth_version must be a nonempty string")
        if not _valid_nonempty_string(policy_version):
            raise BrakeError("policy_version must be a nonempty string")
        self.run_id = run_id
        self.max_turns = max_turns
        self.budget_units = budget_units
        self.auth_version = auth_version
        self.policy_version = policy_version
        self.state = "ACTIVE"
        self.error_result = "NONE"
        self.message = "Ready."
        self.model_calls = 0
        self.usage_units = 0
        self.attempts = 0
        self.executions = 0
        self.pending = None
        self.approval = None

    def _admit(self, allowed=("ACTIVE",)):
        if self.state in TERMINAL:
            raise BrakeError("terminal state blocks admission: " + self.state)
        if self.state not in allowed:
            raise BrakeError("state blocks admission: " + str(self.state))

    def model_call(self, units):
        self._admit()
        if not _valid_int(units, minimum=0):
            raise BrakeError("usage units must be a nonnegative integer")
        if self.model_calls >= self.max_turns:
            self.state = "TURN_LIMIT"
            self.error_result = "MAX_TURNS"
            self.message = "Turn limit reached; no further model calls."
            raise BrakeError(self.message)
        self.model_calls += 1
        self.usage_units += units
        if self.usage_units >= self.budget_units:
            self.state = "BUDGET_LIMIT"
            self.error_result = "BUDGET_THRESHOLD"
            self.message = "Synthetic budget reached after the crossing call; no further model calls."
        return "synthetic-response"

    def request_action(self, action_id, action, arguments, now, approval_ttl):
        self._admit()
        if not _valid_nonempty_string(action_id):
            raise BrakeError("action_id must be a nonempty string")
        if not _valid_nonempty_string(action):
            raise BrakeError("action must be a nonempty string")
        if type(arguments) is not dict:
            raise BrakeError("arguments must be a canonical JSON dictionary")
        arguments_hash = digest(arguments)
        if not _valid_int(now, minimum=0):
            raise BrakeError("now must be a nonnegative integer")
        if not _valid_int(approval_ttl, minimum=1):
            raise BrakeError("approval_ttl must be a positive integer")
        pending = {
            "action_id": action_id,
            "action": action,
            "arguments_hash": arguments_hash,
            "expires_at": now + approval_ttl
        }
        self.attempts += 1
        self.pending = pending
        self.state = "PAUSED"
        self.error_result = "INTERRUPTION"
        self.message = "Approval required before mock effect."

    def decide(self, action_id, approve, reviewer):
        self._admit(("PAUSED",))
        if not _valid_nonempty_string(action_id):
            raise BrakeError("action_id must be a nonempty string")
        if not isinstance(approve, bool):
            raise BrakeError("approve must be a boolean")
        if not _valid_nonempty_string(reviewer):
            raise BrakeError("reviewer must be a nonempty string")
        pending = self.pending
        if not isinstance(pending, dict) or action_id != pending.get("action_id"):
            raise BrakeError("decision does not match pending action")
        if not approve:
            self.state = "DENIED"
            self.error_result = "REJECTED"
            self.message = "Reviewer denied the action; no effect occurred."
            return
        approval = {
            "action_id": action_id,
            "action": pending["action"],
            "arguments_hash": pending["arguments_hash"],
            "auth_version": self.auth_version,
            "policy_version": self.policy_version,
            "expires_at": pending["expires_at"],
            "reviewer": reviewer
        }
        self.approval = approval
        self.state = "APPROVED"
        self.error_result = "APPROVED_PENDING_RESUME"
        self.message = "Approved; authorization and guardrails must be renewed before execution."

    def dumps(self):
        self._admit(("PAUSED", "APPROVED"))
        data = {
            "schema": 1,
            "run_id": self.run_id,
            "max_turns": self.max_turns,
            "budget_units": self.budget_units,
            "auth_version": self.auth_version,
            "policy_version": self.policy_version,
            "state": self.state,
            "error_result": self.error_result,
            "message": self.message,
            "model_calls": self.model_calls,
            "usage_units": self.usage_units,
            "attempts": self.attempts,
            "executions": self.executions,
            "pending": self.pending,
            "approval": self.approval
        }
        return canonical(data)

    @classmethod
    def loads(cls, text):
        if not isinstance(text, str):
            raise BrakeError("malformed saved state")
        try:
            data = json.loads(
                text,
                object_pairs_hook=_object_without_duplicates,
                parse_constant=lambda value: (_ for _ in ()).throw(ValueError(value))
            )
        except (TypeError, ValueError, json.JSONDecodeError, RecursionError) as exc:
            raise BrakeError("malformed saved state") from exc

        required = {
            "schema", "run_id", "max_turns", "budget_units",
            "auth_version", "policy_version", "state", "error_result",
            "message", "model_calls", "usage_units", "attempts",
            "executions", "pending", "approval"
        }
        if type(data) is not dict or set(data) != required:
            raise BrakeError("malformed saved state")
        if not _valid_int(data["schema"], minimum=1, maximum=1):
            raise BrakeError("malformed saved state")
        if not _valid_nonempty_string(data["run_id"]):
            raise BrakeError("malformed saved state")
        if not _valid_int(data["max_turns"], minimum=1):
            raise BrakeError("malformed saved state")
        if not _valid_int(data["budget_units"], minimum=1):
            raise BrakeError("malformed saved state")
        if not _valid_nonempty_string(data["auth_version"]):
            raise BrakeError("malformed saved state")
        if not _valid_nonempty_string(data["policy_version"]):
            raise BrakeError("malformed saved state")
        if not isinstance(data["state"], str) or data["state"] not in {"PAUSED", "APPROVED"}:
            raise BrakeError("saved state is not resumable")
        if not isinstance(data["error_result"], str) or not isinstance(data["message"], str):
            raise BrakeError("malformed saved state")
        if not _valid_int(data["model_calls"], minimum=0, maximum=data["max_turns"]):
            raise BrakeError("malformed saved state")
        if not _valid_int(data["usage_units"], minimum=0):
            raise BrakeError("malformed saved state")
        if data["usage_units"] >= data["budget_units"]:
            raise BrakeError("malformed saved state")
        if not _valid_int(data["attempts"], minimum=1, maximum=1):
            raise BrakeError("malformed saved state")
        if not _valid_int(data["executions"], minimum=0, maximum=0):
            raise BrakeError("malformed saved state")

        pending = data["pending"]
        pending_required = {"action_id", "action", "arguments_hash", "expires_at"}
        if type(pending) is not dict or set(pending) != pending_required:
            raise BrakeError("malformed saved state")
        if not _valid_nonempty_string(pending["action_id"]):
            raise BrakeError("malformed saved state")
        if not _valid_nonempty_string(pending["action"]):
            raise BrakeError("malformed saved state")
        if not _valid_digest(pending["arguments_hash"]):
            raise BrakeError("malformed saved state")
        if not _valid_int(pending["expires_at"], minimum=1):
            raise BrakeError("malformed saved state")

        if data["state"] == "PAUSED":
            if data["approval"] is not None:
                raise BrakeError("malformed saved state")
            if data["error_result"] != "INTERRUPTION":
                raise BrakeError("malformed saved state")
            if data["message"] != "Approval required before mock effect.":
                raise BrakeError("malformed saved state")
        else:
            approval = data["approval"]
            approval_required = {
                "action_id", "action", "arguments_hash", "auth_version",
                "policy_version", "expires_at", "reviewer"
            }
            if type(approval) is not dict or set(approval) != approval_required:
                raise BrakeError("malformed saved state")
            if not _valid_nonempty_string(approval["action_id"]):
                raise BrakeError("malformed saved state")
            if not _valid_nonempty_string(approval["action"]):
                raise BrakeError("malformed saved state")
            if not _valid_digest(approval["arguments_hash"]):
                raise BrakeError("malformed saved state")
            if not _valid_nonempty_string(approval["auth_version"]):
                raise BrakeError("malformed saved state")
            if not _valid_nonempty_string(approval["policy_version"]):
                raise BrakeError("malformed saved state")
            if not _valid_int(approval["expires_at"], minimum=1):
                raise BrakeError("malformed saved state")
            if not _valid_nonempty_string(approval["reviewer"]):
                raise BrakeError("malformed saved state")
            if approval["action_id"] != pending["action_id"]:
                raise BrakeError("malformed saved state")
            if approval["action"] != pending["action"]:
                raise BrakeError("malformed saved state")
            if approval["arguments_hash"] != pending["arguments_hash"]:
                raise BrakeError("malformed saved state")
            if approval["expires_at"] != pending["expires_at"]:
                raise BrakeError("malformed saved state")
            if approval["auth_version"] != data["auth_version"]:
                raise BrakeError("malformed saved state")
            if approval["policy_version"] != data["policy_version"]:
                raise BrakeError("malformed saved state")
            if data["error_result"] != "APPROVED_PENDING_RESUME":
                raise BrakeError("malformed saved state")
            if data["message"] != "Approved; authorization and guardrails must be renewed before execution.":
                raise BrakeError("malformed saved state")

        try:
            run = cls(
                data["run_id"],
                data["max_turns"],
                data["budget_units"],
                data["auth_version"],
                data["policy_version"]
            )
        except BrakeError as exc:
            raise BrakeError("malformed saved state") from exc
        for name in (
            "state", "error_result", "message", "model_calls",
            "usage_units", "attempts", "executions", "pending", "approval"
        ):
            setattr(run, name, data[name])
        return run

    def resume_action(self, action_id, action, arguments, now, current_auth_version, current_policy_version, guardrail_ok, ledger):
        self._admit(("APPROVED",))
        if not _valid_nonempty_string(action_id):
            raise BrakeError("action_id must be a nonempty string")
        if not _valid_nonempty_string(action):
            raise BrakeError("action must be a nonempty string")
        if type(arguments) is not dict:
            raise BrakeError("arguments must be a canonical JSON dictionary")
        arguments_hash = digest(arguments)
        if not _valid_int(now, minimum=0):
            raise BrakeError("now must be a nonnegative integer")
        if not _valid_nonempty_string(current_auth_version):
            raise BrakeError("current_auth_version must be a nonempty string")
        if not _valid_nonempty_string(current_policy_version):
            raise BrakeError("current_policy_version must be a nonempty string")
        if not isinstance(guardrail_ok, bool):
            raise BrakeError("guardrail_ok must be a boolean")
        if type(ledger) is not dict:
            raise BrakeError("ledger must be a dictionary")

        pending = self.pending
        approval = self.approval
        binding_matches = (
            isinstance(pending, dict)
            and isinstance(approval, dict)
            and action_id == pending.get("action_id")
            and action_id == approval.get("action_id")
            and action == pending.get("action")
            and action == approval.get("action")
            and arguments_hash == pending.get("arguments_hash")
            and arguments_hash == approval.get("arguments_hash")
            and pending.get("expires_at") == approval.get("expires_at")
        )
        if not binding_matches:
            self.state = "REVALIDATION_FAILED"
            self.error_result = "ACTION_BINDING_MISMATCH"
            self.message = "Action identity or arguments changed; execution blocked."
            raise BrakeError(self.message)
        if current_auth_version != approval.get("auth_version"):
            self.state = "AUTH_CHANGED"
            self.error_result = "AUTHORIZATION_CHANGED"
            self.message = "Authorization changed during the pause; execution blocked."
            raise BrakeError(self.message)
        if current_policy_version != approval.get("policy_version") or not guardrail_ok:
            self.state = "REVALIDATION_FAILED"
            self.error_result = "POLICY_OR_GUARDRAIL_FAILED"
            self.message = "Renewed policy or guardrail check failed; execution blocked."
            raise BrakeError(self.message)
        expires_at = approval.get("expires_at")
        if not _valid_int(expires_at, minimum=1) or now > expires_at:
            self.state = "STALE_APPROVAL"
            self.error_result = "APPROVAL_EXPIRED"
            self.message = "Approval expired; execution blocked."
            raise BrakeError(self.message)

        if action_id in ledger:
            prior = ledger[action_id]
            if type(prior) is str and prior == "executed":
                self.state = "REPLAY_BLOCKED"
                self.error_result = "DUPLICATE_ACTION"
                self.message = "Replay blocked; mock effect was already recorded."
                raise BrakeError(self.message)
            self.state = "RECONCILIATION_REQUIRED"
            self.error_result = "PARTIAL_EFFECT_UNKNOWN"
            self.message = "Effect status is unknown; reconcile before any new call."
            raise BrakeError(self.message)

        ledger[action_id] = "pending"
        ledger[action_id] = "executed"
        self.executions += 1
        self.state = "COMPLETED"
        self.error_result = "SUCCESS"
        self.message = "Mock effect completed once."
        return {"action": action, "arguments_hash": arguments_hash}
'''

FIXTURES = r'''{
  "secret": "acct-secret-never-persist",
  "action": {"action_id": "refund-001", "name": "mock_refund", "arguments": {"order": "A100", "units": 7}},
  "limits": {"max_turns": 2, "budget_units": 5},
  "approval": {"now": 100, "ttl": 50, "resume_now": 140, "auth_version": "auth-v1", "policy_version": "policy-v1"}
}
