LAB = r'''import json
from pathlib import Path
from simulator import BrakeError, Run

F = json.loads(Path("fixtures.json").read_text())
A = F["action"]
L = F["limits"]
P = F["approval"]
Path("state").mkdir(exist_ok=True)

def paused(run, filename):
    text = run.dumps()
    assert F["secret"] not in text
    Path(filename).write_text(text)
    return filename

def row(name, run, saved="-"):
    return [name, run.state, run.error_result, run.message, saved, str(run.attempts), str(run.executions), str(run.usage_units)]

rows = []

approval = Run("approval", L["max_turns"], L["budget_units"])
approval.request_action(A["action_id"], A["name"], A["arguments"], P["now"], P["ttl"])
approval_ref = paused(approval, "state/approval.json")
assert approval.state == "PAUSED" and approval.executions == 0
rows.append(row("approval_pause", approval, approval_ref))

denial = Run("denial", L["max_turns"], L["budget_units"])
denial.request_action("refund-denied", A["name"], A["arguments"], P["now"], P["ttl"])
denial.decide("refund-denied", False, "reviewer-1")
assert denial.state == "DENIED" and denial.executions == 0
rows.append(row("denial", denial))

turn = Run("turn", 2, 99)
turn.model_call(2)
turn.model_call(2)
try:
    turn.model_call(2)
except BrakeError:
    pass
assert turn.state == "TURN_LIMIT" and turn.model_calls == 2 and turn.usage_units == 4
rows.append(row("turn_limit", turn))

budget = Run("budget", 9, 5)
budget.model_call(3)
budget.model_call(3)
assert budget.state == "BUDGET_LIMIT" and budget.model_calls == 2 and budget.usage_units == 6
try:
    budget.model_call(1)
except BrakeError:
    pass
assert budget.model_calls == 2 and budget.usage_units == 6
rows.append(row("spend_limit", budget))

ledger = {}
recovery = Run("recovery", L["max_turns"], L["budget_units"], P["auth_version"], P["policy_version"])
recovery.request_action(A["action_id"], A["name"], A["arguments"], P["now"], P["ttl"])
recovery.decide(A["action_id"], True, "reviewer-2")
recovery_ref = paused(recovery, "state/recovery.json")
del recovery
recovery = Run.loads(Path(recovery_ref).read_text())
recovery.resume_action(A["action_id"], A["name"], A["arguments"], P["resume_now"], P["auth_version"], P["policy_version"], True, ledger)
assert recovery.state == "COMPLETED" and recovery.executions == 1 and ledger[A["action_id"]] == "executed"
rows.append(row("successful_recovery", recovery, recovery_ref))

print("CASE|TERMINAL_STATE|ERROR_OR_RESULT|MODEL_MESSAGE|SAVED_STATE|ATTEMPTS|EXECUTIONS|SYNTHETIC_USAGE")
for values in rows:
    print("|".join(values))

negative = []
def approved_copy(action_id):
    run = Run("negative-" + action_id, 2, 5, P["auth_version"], P["policy_version"])
    run.request_action(action_id, A["name"], A["arguments"], P["now"], P["ttl"])
    run.decide(action_id, True, "reviewer-negative")
    return Run.loads(run.dumps())

changed = approved_copy("changed-auth")
try:
    changed.resume_action("changed-auth", A["name"], A["arguments"], 120, "auth-v2", P["policy_version"], True, {})
except BrakeError:
    pass
assert changed.state == "AUTH_CHANGED" and changed.executions == 0
negative.append("changed_authorization=" + changed.state)

try:
    Run.loads("{not-json")
except BrakeError as exc:
    malformed = str(exc)
else:
    raise AssertionError("malformed state was accepted")
negative.append("malformed_state=" + malformed)

stale = approved_copy("stale")
try:
    stale.resume_action("stale", A["name"], A["arguments"], 151, P["auth_version"], P["policy_version"], True, {})
except BrakeError:
    pass
assert stale.state == "STALE_APPROVAL" and stale.executions == 0
negative.append("stale_approval=" + stale.state)

try:
    recovery.resume_action(A["action_id"], A["name"], A["arguments"], 141, P["auth_version"], P["policy_version"], True, ledger)
except BrakeError as exc:
    replay_message = str(exc)
else:
    raise AssertionError("replay was accepted")
assert recovery.executions == 1 and ledger[A["action_id"]] == "executed"
negative.append("replay=" + replay_message)

unknown = approved_copy("unknown-effect")
unknown_ledger = {"unknown-effect": "unknown"}
try:
    unknown.resume_action("unknown-effect", A["name"], A["arguments"], 120, P["auth_version"], P["policy_version"], True, unknown_ledger)
except BrakeError:
    pass
assert unknown.state == "RECONCILIATION_REQUIRED" and unknown.executions == 0
try:
    unknown.model_call(1)
except BrakeError as exc:
    unknown_block = str(exc)
else:
    raise AssertionError("unknown effect admitted a new call")
negative.append("unknown_partial_effect=" + unknown.state + ";new_call=" + unknown_block)

for item in negative:
    print("NEGATIVE|" + item)
print("ASSERTIONS|all_passed")
print("NOTICE|synthetic units; no model, billing, network, or external effect")
'''

Path("simulator.py").write_text(SIMULATOR)
Path("fixtures.json").write_text(FIXTURES)
Path("lab.py").write_text(LAB)
print("WROTE|simulator.py|fixtures.json|lab.py")
print("NEXT|python3 lab.py")
